##
## Launcher for the European-specialist workshop deck (Paulo, 2026-11).
## Mirrors run_pbr_report_BSH_DGY.R's convention: settings sourced first,
## figures generated by R, the Rmd only formats what it's handed as
## params. Source this file (or Rscript run_workshop_deck.R) to rebuild
## outputs/pbr_curtailment_workshop_slides.pptx.
##
## To restyle (font size, subtitles on/off, point/symbol size, colours),
## edit deck_plot_controls in inputs/deckSettings_workshop.R and re-run --
## never R/workshop_deck_figures.R or the Rmd.
##

source("inputs/deckSettings_workshop.R")
source("R/workshop_deck_figures.R")

fig_paths <- build_workshop_deck_figures(fig_dir = "outputs/figures")

rmarkdown::render(
  input       = "report/pbr_workshop_slides.Rmd",
  output_file = "pbr_curtailment_workshop_slides.pptx",
  output_dir  = "outputs",
  params = fig_paths
)

message("\nWrote outputs/pbr_curtailment_workshop_slides.pptx\n")
